package com.bluemoon.models;

import java.time.LocalDate;

/**
 * Table `residents`. maNhanKhau is generated by the database: pass 0 for a resident that is not saved yet.
 * soCccd is null when the person has none (only allowed under 14).
 */
public record Resident(long maNhanKhau, String maHo, String hoTen, LocalDate ngaySinh, Gender gioiTinh,
                       String soCccd, RelationToHead quanHeChuHo, LocalDate ngayChuyenDen) {
    public boolean isHead() { return quanHeChuHo == RelationToHead.CHU_HO; }
}
